const metrics = $items('Get All Brand Metrics')[0].json;
const aiSummary = $items('Generate Multi-Brand Summary')[0].json.summary || '';
if (metrics.scope !== 'all_brands' || !Array.isArray(metrics.brands)) {
  throw new Error('WF06 expected an all_brands snapshot with a brands array');
}
const number = value => Number(value || 0);
const money = value => `₹${number(value).toLocaleString('en-IN')}`;
const totals = metrics.totals || {};
const consolidated = [
  '**CONSOLIDATED ALL-BRANDS**',
  `• Configured brands: ${number(totals.brands) || metrics.brands.length} | Active brands: ${number(totals.active_brands)}`,
  `• Leads: ${number(totals.leads)} | New today: ${number(totals.leads_today)} | Hot leads: ${number(totals.hot_leads)} | Pending follow-ups: ${number(totals.followups_pending)}`,
  `• Conversations: ${number(totals.conversations)} | Conversations today: ${number(totals.conversations_today)}`,
  `• Campaigns: ${number(totals.campaigns)} | Active campaigns: ${number(totals.active_campaigns)}`,
  `• Conversions: ${number(totals.conversions)} | Conversion rate: ${number(totals.conversion_rate)}%`,
  `• Total revenue: ${money(totals.revenue)} | Revenue today: ${money(totals.revenue_today)} | Revenue this month: ${money(totals.revenue_month)}`,
  '',
  '**BRAND-WISE BREAKDOWN**',
  ...metrics.brands.flatMap(brand => {
    const sources = Array.isArray(brand.lead_sources) && brand.lead_sources.length
      ? brand.lead_sources.map(source => `${source.source}: ${number(source.count)}`).join(', ')
      : 'None: 0';
    return [
      `• **${brand.brand}** (${brand.brand_status || 'unknown'})`,
      `  Leads: ${number(brand.leads)} | New today: ${number(brand.leads_today)} | Hot: ${number(brand.hot_leads)} | Pending follow-ups: ${number(brand.followups_pending)}`,
      `  Conversations: ${number(brand.conversations)} | Today: ${number(brand.conversations_today)}`,
      `  Campaigns: ${number(brand.campaigns)} | Active: ${number(brand.active_campaigns)}`,
      `  Conversions: ${number(brand.conversions)} | Rate: ${number(brand.conversion_rate)}%`,
      `  Revenue: ${money(brand.revenue)} | Today: ${money(brand.revenue_today)} | Month: ${money(brand.revenue_month)}`,
      `  Lead sources: ${sources}`,
    ];
  }),
];
return [{ json: { summary: `${consolidated.join('\n')}\n\n**AI EXECUTIVE INSIGHT**\n${aiSummary}` } }];
